contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address other) public payable {
        require(other != address(this));
        uint256 beforeOther = c.getBalance(other); if (__ESBMC_reverted()) return;
        uint256 beforeSelf = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterSelf = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterOther = c.getBalance(other); if (__ESBMC_reverted()) return;

        assert(!reverted && afterSelf == 0 && afterOther == beforeOther);
    }
}

